.users-table__wrapper {
  width: 100%;
  min-height: calc(100svh - 55px);
  background: var(--color-surface);
}

.users-table {
  width: 100%;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  font-size: 14px;
  line-height: 1.4;
  color: var(--color-text);

  &__head {
    display: none;
  }

  &__row {
    display: block;
    width: calc(100% - 2rem);
    margin: 1rem;
    border: 1px solid var(--color-border);
    background: var(--color-surface);
    box-shadow: var(--shadow-sm);
    overflow: hidden;
    transition: background-color 0.15s ease;

    &:hover {
      background: var(--color-surface);
    }
  }

  &__cell {
    display: flex;
    align-items: flex-start;
    flex-direction: column;
    justify-content: space-between;
    width: 100%;
    min-width: 0;
    gap: 4px;
    padding: 12px 14px;
    border-bottom: 1px solid var(--color-border-subtle);
    white-space: normal;
    text-align: left;
    overflow-wrap: anywhere;

    &::before {
      content: attr(data-label);
      flex: 0 0 auto;
      color: var(--color-text-secondary);
      font-size: 11px;
      font-weight: 600;
      line-height: 1.2;
      letter-spacing: 0.05em;
      text-align: left;
      text-transform: uppercase;
    }

    &:first-child {
      font-weight: 500;
      color: var(--color-text);
    }

    &:last-child {
      align-items: stretch;
      width: 100%;
      padding-right: 14px;
      border-bottom: 0;

      &::before {
        margin-bottom: 4px;
      }
    }
  }

  &__empty {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    padding: 2rem;
    text-align: center;
  }

  &__empty-message {
    margin: 0;
    color: var(--color-text-secondary);
    font-size: 14px;
  }
}

.actions {
  &__buttons {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    align-items: center;
    width: 100%;
    gap: 6px;
  }

  &__button {
    appearance: none;
    -webkit-appearance: none;
    width: 100%;
    min-width: 0;
    min-height: 34px;
    padding: 8px 6px;
    border-width: 1px;
    border-style: solid;
    border-color: var(--color-border);
    border-radius: 6px;
    background: var(--color-surface);
    color: var(--color-text-secondary);
    font-family: inherit;
    font-size: 13px;
    font-weight: 500;
    line-height: 1;
    text-align: center;
    white-space: nowrap;
    cursor: pointer;
    transition:
      background-color 0.15s ease,
      border-color 0.15s ease,
      color 0.15s ease,
      box-shadow 0.15s ease,
      transform 0.1s ease;

    &:focus-visible {
      outline: 2px solid var(--color-focus);
      outline-offset: 2px;
    }

    &:active {
      transform: translateY(1px);
    }

    &--select {
      color: var(--color-accent);
      border-color: var(--color-accent);

      &:hover {
        color: var(--color-text-on-accent);
        background: var(--color-accent);
        border-color: var(--color-accent);
      }

      &:active {
        background: var(--color-accent-active);
        border-color: var(--color-accent-active);
      }
    }

    &--edit {
      color: var(--color-info);
      border-color: var(--color-info);

      &:hover {
        background: var(--color-info-soft);
        border-color: var(--color-info);
      }

      &:active {
        background: var(--color-surface-active);
        border-color: var(--color-info);
      }
    }

    &--remove {
      color: var(--color-danger);
      border-color: var(--color-danger);

      &:hover {
        background: var(--color-danger-soft);
        border-color: var(--color-danger);
      }

      &:active {
        background: var(--color-danger-soft);
        border-color: var(--color-danger);
      }
    }
  }
}

@media (min-width: 425px) {
  .users-table {
    &__cell {
      align-items: center;
      flex-direction: row;
      gap: 20px;
      text-align: right;

      &::before {
        font-size: 12px;
        line-height: 1.3;
        letter-spacing: 0.01em;
        text-transform: none;
      }

      &:last-child {
        align-items: center;
      }
    }
  }

  .actions {
    &__buttons {
      display: flex;
      justify-content: flex-end;
      width: 100%;
      gap: 6px;
    }

    &__button {
      flex: 0 0 auto;
      width: auto;
      min-width: max-content;
      min-height: 34px;
      padding: 7px 12px;
    }
  }
}

@media (min-width: 768px) {
  .users-table__wrapper {
    width: 100%;
    height: calc(100svh - 55px);
    overflow: auto;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    box-shadow: var(--shadow-sm);
  }

  .users-table {
    width: 100%;
    margin: 0 auto;
    background: transparent;
    border: 0;
    border-collapse: collapse;
    border-spacing: 0;
    border-radius: 0;
    box-shadow: none;
    overflow: visible;

    &__head {
      display: table-header-group;
      position: sticky;
      top: 0;
      z-index: 2;
      background: var(--color-surface-hover);

      .users-table__cell {
        background: var(--color-surface-hover);
        color: var(--color-text-secondary);
        font-size: 12px;
        font-weight: 600;
        text-align: left;
        text-transform: uppercase;
        letter-spacing: 0.02em;
        border: 0;

        &:first-child {
          font-weight: 600;
        }

        &:last-child {
          text-align: right;
        }
      }
    }

    &__row {
      display: table-row;
      width: auto;
      margin: 0;
      border-top: 1px solid var(--color-border-subtle);
      border-bottom: 1px solid var(--color-border-subtle);
      background: transparent;
      box-shadow: none;

      &:hover {
        background: var(--color-surface-hover);
      }

      &:first-child {
        border-top: 0;
      }
    }

    &__cell {
      display: table-cell;
      width: auto;
      min-width: 0;
      padding: 14px 16px;
      border: 0;
      background: transparent;
      vertical-align: middle;
      white-space: nowrap;
      text-align: left;

      &::before {
        display: none;
      }

      &:first-child {
        font-weight: 500;
        color: var(--color-text);
      }

      &:last-child {
        width: 1%;
        padding-right: 12px;
      }
    }
  }

  .actions {
    &__buttons {
      display: flex;
      align-items: center;
      justify-content: flex-end;
      width: auto;
      gap: 6px;
    }

    &__button {
      min-height: 32px;
      padding: 6px 11px;
      border-width: 1px;
      border-style: solid;

      &--select {
        border-color: var(--color-accent);
      }

      &--edit {
        border-color: var(--color-info);
      }

      &--remove {
        border-color: var(--color-danger);
      }
    }
  }
}

